CREATE POLICY "team_log_anon_select" ON team_log_entries FOR SELECT TO anon USING (true);
CREATE POLICY "team_log_anon_insert" ON team_log_entries FOR INSERT TO anon WITH CHECK (true);

-- 기존 로그인 계정도 동일하게 조회/작성 가능
